import os, sys, base64
os.environ.setdefault('DJANGO_SETTINGS_MODULE', 'config.settings.production')
import django; django.setup()
from django.core.files.base import ContentFile
from django.apps import apps

entries = [{"model": "shop.Product", "lookup": "slug", "value": "neroli-imperial", "field": "main_image", "data": "", "ext": "webp"}, {"model": "shop.Product", "lookup": "slug", "value": "ashwagandha-sombre", "field": "main_image", "data": "", "ext": "webp"}, {"model": "shop.Product", "lookup": "slug", "value": "moringa-solaire", "field": "main_image", "data": "", "ext": "webp"}, {"model": "shop.Product", "lookup": "slug", "value": "songe-dosiris", "field": "main_image", "data": "", "ext": "webp"}, {"model": "shop.Product", "lookup": "slug", "value": "quintessence-dhematite", "field": "main_image", "data": "", "ext": "webp"}, {"model": "core.HeroSlide", "lookup": "page", "value": "home", "field": "image", "data": "", "ext": "webp"}, {"model": "core.HeroSlide", "lookup": "page", "value": "login", "field": "image", "data": "", "ext": "webp"}, {"model": "blog.Article", "lookup": "slug", "value": "le-pouvoir-adaptogene-de-lashwagandha", "field": "featured_image", "data": "", "ext": "webp"}, {"model": "blog.Article", "lookup": "slug", "value": "protocoles-de-detoxification-hepatique-douce", "field": "featured_image", "data": "", "ext": "webp"}, {"model": "blog.Article", "lookup": "slug", "value": "microbiote-et-axe-intestin-cerveau", "field": "featured_image", "data": "", "ext": "webp"}, {"model": "blog.Article", "lookup": "slug", "value": "les-5-piliers-dune-digestion-optimale", "field": "featured_image", "data": "", "ext": "webp"}, {"model": "blog.Article", "lookup": "slug", "value": "jeune-intermittent-mythes-et-realites-cliniques", "field": "featured_image", "data": "", "ext": "webp"}, {"model": "blog.Article", "lookup": "slug", "value": "gemmotherapie-le-pouvoir-des-bourgeons", "field": "featured_image", "data": "", "ext": "webp"}, {"model": "blog.Article", "lookup": "slug", "value": "aromatherapie-scientifique", "field": "featured_image", "data": "", "ext": "webp"}, {"model": "blog.Article", "lookup": "slug", "value": "le-rituel-du-matin", "field": "featured_image", "data": "", "ext": "webp"}]

for entry in entries:
    try:
        model = apps.get_model(entry["model"])
        obj = model.objects.get(**{entry["lookup"]: entry["value"]})
        filename = f"{entry["value"]}_{entry["field"]}.{entry["ext"]}"
        getattr(obj, entry["field"]).save(
            filename,
            ContentFile(base64.b64decode(entry["data"]), name=filename),
            save=True,
        )
        print(f"OK: {entry["model"]}#{entry["value"]}")
    except Exception as e:
        print(f"FAIL: {entry["model"]}#{entry["value"]}: {e}")
print("All done!")
